mapper.update:
UPDATE MB_FRAGMENT SET
	UPDATED_AT = CURRENT_TIMESTAMP
	, IS_DELETED = 1
WHERE 1=1
	AND USER_NO = #{userNo}
	AND UID = #{uid}

UPDATE MB_FRAGMENT SET
	UPDATED_AT = CURRENT_TIMESTAMP
	, CONTENT = #{req.content}
	, IP = #{req.ip}
WHERE 1=1
	AND USER_NO = #{userNo}
	AND UID = #{req.uid}

INSERT INTO MB_FRAGMENT_IMAGE (
	UID
	, FRAGMENT_NO
	, USER_NO
	, IMAGE_ORDER
	, MIME_TYPE
	, STORAGE_NAME
	, ORIGINAL_NAME
	, WIDTH
	, HEIGHT
	, FILE_SIZE
)
VALUES (
	#{item.uid}
	, #{fragment}
	, #{user.userNo}
	, #{item.imageOrder}
	, #{item.mimeType}
	, #{item.storageName}
	, #{item.originalName}
	, #{item.width}
	, #{item.height}
	, #{item.fileSize}
)
ON CONFLICT(FRAGMENT_NO, IMAGE_ORDER) DO UPDATE SET
	UID = excluded.UID,
	USER_NO = excluded.USER_NO,
	MIME_TYPE = excluded.MIME_TYPE,
	STORAGE_NAME = excluded.STORAGE_NAME,
	ORIGINAL_NAME = excluded.ORIGINAL_NAME,
	WIDTH = excluded.WIDTH,
	HEIGHT = excluded.HEIGHT,
	FILE_SIZE = excluded.FILE_SIZE,
	UPDATED_AT = CURRENT_TIMESTAMP
